mapper.sql:
/* 사용요청 처리시에는 reqPt(사용요청포인트) 입력하고, 사용선조회시에는 reqPt(사용요청포인트) 미입력으로 최대사용가능포인트 조회 */ SELECT B.LIMIT_YN, B.PT_NO, B.MEMBER_PT_NO, C.CONT_NO, C.CONT_NM, B.BAL_PT, B.ISU_DT, B.USE_END_DT, B.ACC_BAL_PT FROM (SELECT LIMIT_YN, PT_NO, MEMBER_PT_NO, CONT_NO, BAL_PT, ISU_DT, USE_END_DT ,SUM(ACC_BAL_PT) OVER (ORDER BY USE_END_DT ASC, ISU_DT ASC, BAL_PT DESC, PT_NO ASC) AS ACC_BAL_PT FROM ( SELECT (CASE WHEN CM.ONCE_USE_LIMIT_TYPE_CD IS NULL OR CM.ONCE_USE_LIMIT_TYPE_CD IN ('NONE', 'MIN') THEN 0 ELSE 1 END) AS LIMIT_YN, PM.PT_NO, PM.MEMBER_PT_NO, PM.CONT_NO, PM.BAL_PT, ID.ISU_DT, PM.USE_END_DT, ID.ACC_BAL_PT FROM T_PT_MST PM INNER JOIN T_CONT_MST CM ON CM.CONT_NO = PM.CONT_NO AND CM.PT_TYPE_CD = 'MILEAGE' AND CM.CONT_STS_CD = 'NORMAL' AND (CURRENT_TIMESTAMP(6) BETWEEN CM.START_DT AND CM.END_DT) AND (CURRENT_TIMESTAMP(6) BETWEEN CM.USE_START_DT AND CM.USE_END_DT)
AND CM.CONT_NO IN
#{contNo}
INNER JOIN ( SELECT T1.TR_SNO, T1.TR_SEQ, T1.PT_NO, T1.TR_DT AS ISU_DT, T2.ACC_BAL_PT FROM T_TR_HIST_DETAIL T1 INNER JOIN ( SELECT TT.TR_SNO, TT.TR_SEQ, TT.ACC_BAL_PT FROM (SELECT THD.TR_SNO, THD.TR_SEQ, THD.PT_NO, THD.CONT_NO, THD.TR_PT AS ISU_PT, PMB.BASE_BAL_PT, SUM(THD.TR_PT) OVER (ORDER BY THD.TR_SNO ASC, THD.TR_SEQ ASC) AS ACC_BAL_PT FROM T_TR_HIST_DETAIL THD -- 마일리지형은 동일일자 여러건 적립시 일자별로 PT_MST를 누적 관리하므로 차감된 포인트를 제외한 포인트들중에서 -- 가장 먼저 적립한 ISU_DT를 유추함 INNER JOIN (SELECT PM1.PT_NO, (SUM(PM1.USE_PT) + SUM(PM1.ISU_CANCEL_PT) - SUM(PM1.USE_CANCEL_PT)) AS BASE_BAL_PT FROM T_PT_MST PM1 WHERE PM1.MEMBER_NO = #{memberNo} AND PM1.BAL_PT > 0 AND (CURRENT_TIMESTAMP(6) BETWEEN PM1.USE_START_DT AND PM1.USE_END_DT) GROUP BY PM1.PT_NO) AS PMB ON PMB.PT_NO = THD.PT_NO WHERE THD.PT_NO = PMB.PT_NO AND THD.MEMBER_NO = #{memberNo} AND THD.TR_GB_CD = 'S001' AND THD.BEF_BAL_PT <= PMB.BASE_BAL_PT GROUP BY THD.TR_SNO, THD.TR_SEQ, THD.PT_NO, THD.CONT_NO, THD.TR_PT ORDER BY THD.TR_SNO DESC, THD.TR_SEQ DESC) TT WHERE TT.ACC_BAL_PT >= TT.BASE_BAL_PT
AND TT.ACC_BAL_PT < #{reqPt}
ORDER BY TT.TR_SNO DESC, TT.TR_SEQ DESC ) AS T2 ON T1.TR_SNO = T2.TR_SNO AND T1.TR_SEQ = T2.TR_SEQ ) AS ID ON ID.PT_NO = PM.PT_NO WHERE PM.EXP_DT > CURRENT_TIMESTAMP(6) AND PM.BAL_PT > 0 UNION ALL SELECT LIMIT_YN, PT_NO, MEMBER_PT_NO, CONT_NO, BAL_PT, ISU_DT, USE_END_DT, ACC_BAL_PT FROM ( SELECT (CASE WHEN CM.ONCE_USE_LIMIT_TYPE_CD IS NULL OR CM.ONCE_USE_LIMIT_TYPE_CD IN ('NONE', 'MIN') THEN 0 ELSE 1 END) AS LIMIT_YN, PM.PT_NO, PM.MEMBER_PT_NO, PM.CONT_NO, PM.BAL_PT, PM.ISU_DT, PM.USE_END_DT, SUM(PM.BAL_PT) OVER (ORDER BY PM.USE_END_DT ASC, PM.BAL_PT DESC, PM.PT_NO ASC) AS ACC_BAL_PT FROM T_PT_MST PM INNER JOIN T_CONT_MST CM ON CM.CONT_NO = PM.CONT_NO AND CM.PT_TYPE_CD = 'COUPON' AND CM.CONT_STS_CD = 'NORMAL' AND (CURRENT_TIMESTAMP(6) BETWEEN CM.START_DT AND CM.END_DT) AND (CURRENT_TIMESTAMP(6) BETWEEN CM.USE_START_DT AND CM.USE_END_DT)
AND CM.CONT_NO IN
#{contNo}
WHERE PM.MEMBER_NO = #{memberNo} AND PM.EXP_DT > CURRENT_TIMESTAMP(6) AND PM.BAL_PT > 0 AND (CURRENT_TIMESTAMP(6) BETWEEN PM.USE_START_DT AND PM.USE_END_DT) ORDER BY PM.USE_END_DT ASC, PM.BAL_PT DESC, PM.PT_NO ASC ) AS C ORDER BY LIMIT_YN DESC, USE_END_DT ASC, ISU_DT ASC, BAL_PT DESC, PT_NO ASC ) AS A ORDER BY LIMIT_YN DESC, USE_END_DT ASC, ISU_DT ASC, BAL_PT DESC, PT_NO ASC ) AS B INNER JOIN CONT_MST C ON B.CONT_NO = C.CONT_NO

mapper.select:
SELECT PT_NO ,MEMBER_PT_NO ,MEMBER_NO ,CONT_NO ,ORG_NO ,ISU_DY ,ISU_DT ,BAL_PT ,ISU_PT ,ISU_CANCEL_PT ,USE_PT ,USE_CANCEL_PT ,USE_START_DT ,USE_END_DT ,EXP_DT ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT FROM T_PT_MST WHERE 1 = 1
AND PT_NO = #{ptNo}
AND MEMBER_NO = #{memberNo}
AND CONT_NO = #{contNo}
AND ISU_DY = #{isuDy}

SELECT
      pm.PT_NO
     ,CASE WHEN #{trGbCd} = 'S001' THEN pm.BAL_PT - #{trPt}
           WHEN #{trGbCd} = 'SC01' THEN pm.BAL_PT + #{trPt}
           WHEN #{trGbCd} = 'U001' THEN pm.BAL_PT + #{trPt}
           WHEN #{trGbCd} = 'UC01' THEN pm.BAL_PT - #{trPt}
           WHEN #{trGbCd} = 'EX01' THEN pm.BAL_PT + #{trPt}
      END AS BEF_BAL_PT
     ,CASE WHEN #{trGbCd} = 'S001' THEN pm.BAL_PT
           WHEN #{trGbCd} = 'SC01' THEN pm.BAL_PT
           WHEN #{trGbCd} = 'U001' THEN pm.BAL_PT
           WHEN #{trGbCd} = 'UC01' THEN pm.BAL_PT
           WHEN #{trGbCd} = 'EX01' THEN pm.BAL_PT
      END AS AFR_BAL_PT
FROM T_PT_MST pm
WHERE pm.PT_NO = #{ptNo}

/* 포인트마스터의 유효 잔여 포인트 합계 */ SELECT pm.CONT_NO, COALESCE(SUM(pm.BAL_PT), 0) AS CONT_BAL_PT FROM T_PT_MST pm INNER JOIN T_CONT_MST cm ON cm.CONT_NO = pm.CONT_NO AND CURRENT_TIMESTAMP(6) BETWEEN cm.START_DT AND cm.END_DT AND cm.CONT_STS_CD = 'NORMAL' WHERE pm.CONT_NO IN
#{contNo}
AND pm.MEMBER_NO = #{memberNo} AND pm.USE_END_DT > CURRENT_TIMESTAMP(6) AND pm.EXP_DT > CURRENT_TIMESTAMP(6) AND pm.BAL_PT > 0 GROUP BY pm.CONT_NO

/* 사용요청 처리시에는 reqPt(사용요청포인트) 입력, 사용선조회시에는 reqPt(사용요청포인트) 미입력으로 최대사용가능포인트 조회 */
WITH TARGET_TABLE (
    LIMIT_YN, PT_NO, MEMBER_PT_NO, CONT_NO, CONT_NM, BAL_PT, ISU_DT, USE_END_DT, ACC_BAL_PT
) AS (

)
(
    SELECT
        @num:=@num+1 AS TR_SEQ, LIMIT_YN, PT_NO, MEMBER_PT_NO, CONT_NO, CONT_NM, BAL_PT, ACC_BAL_PT
       , (CASE WHEN GB = 0 THEN SUM(USE_PT) OVER (ORDER BY @num ASC)
               WHEN GB = 1 THEN BAL_PT - SUM(USE_PT) OVER (ORDER BY @num ASC)
         END) AS USE_PT
    FROM
        (SELECT @num:=0) AS n,
        (
            (
                SELECT 0 AS GB, LIMIT_YN, PT_NO, MEMBER_PT_NO, CONT_NO, CONT_NM, BAL_PT, ACC_BAL_PT, BAL_PT AS USE_PT
                  FROM T_TARGET_TABLE TT1

                    WHERE ACC_BAL_PT  <  #{reqPt}

            )

            UNION ALL
            (
                SELECT 1 AS GB, LIMIT_YN, PT_NO, MEMBER_PT_NO, CONT_NO, CONT_NM, BAL_PT, ACC_BAL_PT, BAL_PT- #{reqPt} AS USE_PT
                  FROM T_TARGET_TABLE TT2
                WHERE ACC_BAL_PT   >=  #{reqPt}
                 LIMIT 1
            )

        ) AS A
)

mapper.update:
UPDATE T_PT_MST
SET   BAL_PT = BAL_PT - #{reqPt}
      ,USE_PT = USE_PT + #{reqPt}
      ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
      ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE
    PT_NO = #{ptNo}

UPDATE T_PT_MST
SET   BAL_PT = BAL_PT + #{reqPt}
      ,USE_CANCEL_PT = USE_CANCEL_PT + #{reqPt}
      ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
      ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE
    PT_NO = #{ptNo}

UPDATE T_PT_MST
   SET   BAL_PT = BAL_PT + #{reqPt}
       ,ISU_PT = ISU_PT + #{reqPt}
       ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
       ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE
    PT_NO = #{ptNo}

UPDATE T_PT_MST
   SET   BAL_PT = BAL_PT - #{reqPt}
       ,ISU_CANCEL_PT = ISU_CANCEL_PT + #{reqPt}
       ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
       ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE
    PT_NO = #{ptNo}

UPDATE T_PT_MST pm JOIN (
SELECT #{ptReqDto.ptNo} AS PT_NO, #{ptReqDto.reqPt} AS REQ_PT
) tt ON tt.PT_NO = pm.PT_NO SET pm.BAL_PT = pm.BAL_PT - tt.REQ_PT ,pm.USE_PT = pm.USE_PT + tt.REQ_PT ,pm.LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR} ,pm.LAST_MOD_DT= CURRENT_TIMESTAMP(6)

UPDATE T_PT_MST pm JOIN (
SELECT #{ptReqDto.ptNo} AS PT_NO, #{ptReqDto.reqPt} AS REQ_PT
) tt ON tt.PT_NO = pm.PT_NO SET pm.BAL_PT = pm.BAL_PT + tt.REQ_PT ,pm.USE_CANCEL_PT = pm.USE_CANCEL_PT + tt.REQ_PT ,pm.LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR} ,pm.LAST_MOD_DT= CURRENT_TIMESTAMP(6)

UPDATE T_PT_MST pm JOIN (
SELECT #{ptReqDto.ptNo} AS PT_NO, #{ptReqDto.reqPt} AS REQ_PT
) tt ON tt.PT_NO = pm.PT_NO SET pm.BAL_PT = pm.BAL_PT - tt.REQ_PT ,pm.ISU_CANCEL_PT = pm.ISU_CANCEL_PT + tt.REQ_PT ,pm.LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR} ,pm.LAST_MOD_DT= CURRENT_TIMESTAMP(6)

mapper.select:
SELECT
    COALESCE(COUNT(pm.PT_NO), 0)
FROM T_PT_MST pm
    INNER JOIN T_CONT_MST cm ON cm.CONT_NO = pm.CONT_NO

                AND (STR_TO_DATE(#{baseDt}, '%Y%m%d%H%i%S') BETWEEN cm.START_DT AND cm.END_DT)


                AND cm.CONT_STS_CD = #{contStsCd}

WHERE pm.MEMBER_NO = #{memberNo}
AND pm.USE_END_DT  >  CURRENT_TIMESTAMP(6)
AND pm.EXP_DT  >  CURRENT_TIMESTAMP(6)

    AND pm.CONT_NO = #{contNo}


    AND (pm.ISU_DT  >=  #{isuStartDt} AND pm.ISU_DT  <  #{isuEndDt})


    AND (STR_TO_DATE(#{baseDt}, '%Y%m%d%H%i%S') BETWEEN pm.USE_START_DT AND pm.USE_END_DT)


    AND pm.BAL_PT  >  #{baseBalPt}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY pm.PT_NO) ROW_NUM ,pm.PT_NO ,pm.MEMBER_PT_NO ,pm.MEMBER_NO ,pm.CONT_NO ,pm.ORG_NO ,pm.ISU_DY ,pm.ISU_DT ,pm.BAL_PT ,pm.ISU_PT ,pm.ISU_CANCEL_PT ,pm.USE_PT ,pm.USE_CANCEL_PT ,pm.USE_START_DT ,pm.USE_END_DT ,pm.USE_CANCEL_START_DT ,pm.USE_CANCEL_END_DT ,pm.EXP_DT ,pm.REG_USER_ID ,pm.REG_DT ,pm.LAST_MOD_USER_ID ,pm.LAST_MOD_DT FROM T_PT_MST pm INNER JOIN T_CONT_MST cm ON cm.CONT_NO = pm.CONT_NO
AND (STR_TO_DATE(#{baseDt}, '%Y%m%d%H%i%S') BETWEEN cm.START_DT AND cm.END_DT)
AND cm.CONT_STS_CD = #{contStsCd}
WHERE pm.MEMBER_NO = #{memberNo} AND pm.USE_END_DT > CURRENT_TIMESTAMP(6) AND pm.EXP_DT > CURRENT_TIMESTAMP(6)
AND pm.CONT_NO = #{contNo}
AND (pm.ISU_DT >= #{isuStartDt} AND pm.ISU_DT < #{isuEndDt})
AND (STR_TO_DATE(#{baseDt}, '%Y%m%d%H%i%S') BETWEEN pm.USE_START_DT AND pm.USE_END_DT)
AND pm.BAL_PT > #{baseBalPt}
ORDER BY PT_NO ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
